// === Tab: Plucker ===
class Plucker {
	constructor(x, id, nodes) {
		this.x = x;
		this.id = id;
		this.wamp = 0;
		this.damp = 0;
		this.amp = 0.2;
		this.nodes = nodes;
		this.osc = [];
		this.freq = base_freq + base_freq * intervals[this.id - 1] / 12;
		this.playing = false;
		this.oscIndex = 0;
		this.pan = map(this.x, -width / 3, 2 * width / 3, -1, 1);
		//To reduce the popping that occurs when an oscillator is started when already playing
		//I create 12 oscillators per string, so a different one starts every time
		//While the remaining ones continue dampening
		for (let i = 0; i < 12; i++) {
			this.osc.push(new p5.Oscillator('sine'));
		}
	}
	show() {
		stroke(255);
		strokeWeight(height / 150);
		this.wamp += this.damp;
		this.damp -= this.wamp;
		let steps = this.nodes * 180 / height;
		noFill();
		beginShape();
		curveVertex(this.x, 0);
		for (let y = 0; y < height; y += 10) {
			let x;
			if (mode == 'harmonic') x = this.x + this.wamp * sin(steps * y);
			else x = this.x + this.wamp * sin(y * 180 / height);
			curveVertex(x, y);
		}
		curveVertex(this.x, height);
		endShape();
		this.damp *= 0.95;
	}
	play() {
		this.oscIndex = (this.oscIndex + 1) % this.osc.length;
		this.osc[this.oscIndex].start();
		this.osc[this.oscIndex].freq(this.freq, 0.1);
		this.osc[this.oscIndex].amp(this.amp, 0.1);
		this.osc[this.oscIndex].amp(0, 2.0);
		this.osc[this.oscIndex].pan(this.pan);
	}
}

